// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(this));
        vm.assume(caller != address(0));

        address originalOwner = c.owner();

        vm.prank(caller);
        address currentOwner = c.owner();

        assertTrue(currentOwner == originalOwner, "owner() should be constant regardless of caller");
    }
}

